def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[+\-*/(),:=<>]")
    values = {}
    active = set()

    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "u-": 3,
    }

    def parse(formula):
        tokens = token_pattern.findall(formula)
        operators = []
        nodes = []
        commas = []
        expecting_operand = True
        i = 0

        def reduce_operator():
            op = operators.pop()
            if op == "u-":
                nodes.append(("unary", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                nodes.append(("number", int(token)))
                expecting_operand = False
            elif token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(token)
                expecting_operand = True
            elif token[0].isalpha():
                if i + 1 < len(tokens) and tokens[i + 1] == ":":
                    other = tokens[i + 2]
                    col1, row1 = ord(token[0]), int(token[1:])
                    col2, row2 = ord(other[0]), int(other[1:])
                    references = []
                    for row in range(min(row1, row2), max(row1, row2) + 1):
                        for col in range(min(col1, col2), max(col1, col2) + 1):
                            name = chr(col) + str(row)
                            if name in cells:
                                references.append(("reference", name))
                    nodes.append(("range", references))
                    i += 2
                else:
                    nodes.append(("reference", token))
                expecting_operand = False
            elif token == "(":
                operators.append(token)
                commas.append(0)
                expecting_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                commas[-1] += 1
                expecting_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = commas.pop() + 1
                if operators and operators[-1] in ("SUM", "MIN", "MAX", "IF"):
                    function = operators.pop()
                    args = nodes[-count:]
                    del nodes[-count:]
                    if function == "IF":
                        nodes.append(("if", args[0], args[1], args[2]))
                    else:
                        expanded = []
                        for arg in args:
                            if arg[0] == "range":
                                expanded.extend(arg[1])
                            else:
                                expanded.append(arg)
                        nodes.append(("aggregate", function, expanded))
                expecting_operand = False
            else:
                op = "u-" if token == "-" and expecting_operand else token
                while (
                    operators
                    and operators[-1] in precedence
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "u-"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(op)
                expecting_operand = True

            i += 1

        while operators:
            reduce_operator()
        return nodes[0]

    def evaluate(start):
        tasks = [("cell", start)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in values:
                    results.append(values[name])
                elif name not in cells:
                    results.append(0)
                elif name in active:
                    results.append("#CYCLE!")
                else:
                    active.add(name)
                    content = cells[name]
                    tasks.append(("finish_cell", name))
                    if content.startswith("="):
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        results.append(int(content))

            elif kind == "finish_cell":
                name = task[1]
                values[name] = results[-1]
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]
                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "reference":
                    tasks.append(("cell", node[1]))
                elif node_kind == "unary":
                    tasks.append(("unary",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                elif node_kind == "if":
                    tasks.append(("if", node[2], node[3]))
                    tasks.append(("eval", node[1]))
                else:
                    tasks.append(("aggregate", node[1], node[2], 0, None))

            elif kind == "unary":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(left == right)
                elif op == "<>":
                    results.append(left != right)
                elif op == "<":
                    results.append(left < right)
                elif op == "<=":
                    results.append(left <= right)
                elif op == ">":
                    results.append(left > right)
                else:
                    results.append(left >= right)

            elif kind == "if":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate":
                function, args, index, accumulator = task[1:]
                if index == len(args):
                    results.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append(("aggregate_value", function, args, index, accumulator))
                    tasks.append(("eval", args[index]))

            else:
                function, args, index, accumulator = task[1:]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if accumulator is None:
                        accumulator = value
                    elif function == "SUM":
                        accumulator += value
                    elif function == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)
                    tasks.append(("aggregate", function, args, index + 1, accumulator))

        return results[0]

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
